import json
import os
import sys
import numpy as np
import pandas as pd

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"

df = pd.read_excel(DATA_FILE, sheet_name="PET")
df.columns = [str(c).strip() for c in df.columns]

temperature_col = next(c for c in df.columns if "Temperature" in c)
weight_col = next(c for c in df.columns if "Weight" in c and "Deriv" not in c)
deriv_col = next(c for c in df.columns if "Deriv" in c)

temperature = pd.to_numeric(df[temperature_col], errors="coerce")
weight = pd.to_numeric(df[weight_col], errors="coerce")
deriv = pd.to_numeric(df[deriv_col], errors="coerce")
valid = temperature.notna() & weight.notna() & deriv.notna()

t = temperature[valid].to_numpy(dtype=float)
w = weight[valid].to_numpy(dtype=float)
d = deriv[valid].to_numpy(dtype=float)

weight_data = [[round(float(x), 6), round(float(y), 6)] for x, y in zip(t, w)]
deriv_data = [[round(float(x), 6), round(float(y), 6)] for x, y in zip(t, d)]

